def transform(grid):
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    r0 = min(r for r, c in ones)
    r1 = max(r for r, c in ones)
    c0 = min(c for r, c in ones)
    c1 = max(c for r, c in ones)
    panel = [row[c0:c1 + 1] for row in grid[r0:r1 + 1]]
    ph, pw = len(panel), len(panel[0])

    inside = {}
    outside = {}
    for r in range(h):
        for c in range(w):
            if r0 <= r <= r1 and c0 <= c <= c1:
                inside.setdefault(grid[r][c], []).append((r - r0, c - c0))
            elif grid[r][c] != 0:
                outside.setdefault(grid[r][c], []).append((r, c))

    colors = [
        color for color in inside
        if color != 1 and len(inside[color]) == 1
        and len(outside.get(color, [])) == 1
    ]

    transforms = [
        lambda r, c: (r, c),
        lambda r, c: (r, pw - 1 - c),
        lambda r, c: (ph - 1 - r, c),
        lambda r, c: (ph - 1 - r, pw - 1 - c),
        lambda r, c: (c, r),
        lambda r, c: (pw - 1 - c, ph - 1 - r),
        lambda r, c: (c, ph - 1 - r),
        lambda r, c: (pw - 1 - c, r),
    ]

    def sign(x):
        return (x > 0) - (x < 0)

    best = transforms[0]
    best_score = -1
    for fn in transforms:
        mapped = {color: fn(*inside[color][0]) for color in colors}
        score = 0
        for i, a in enumerate(colors):
            for b in colors[i + 1:]:
                ext_a, ext_b = outside[a][0], outside[b][0]
                in_a, in_b = mapped[a], mapped[b]
                score += sign(in_a[0] - in_b[0]) == sign(ext_a[0] - ext_b[0])
                score += sign(in_a[1] - in_b[1]) == sign(ext_a[1] - ext_b[1])
        if score > best_score:
            best_score = score
            best = fn

    oh, ow = (pw, ph) if best(0, 0)[0] != best(0, 1)[0] else (ph, pw)
    out = [[0] * ow for _ in range(oh)]
    for r in range(ph):
        for c in range(pw):
            nr, nc = best(r, c)
            out[nr][nc] = panel[r][c]
    return out
